CREATE OR REPLACE FUNCTION public.carregar_painel_controle_acesso(p_nome_usuario character varying, p_senha text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
